<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

int main() {
    int total, factor;
    cin >> total >> factor;
    vector<int> parent(total + 1), rank(total + 1, 1);
    for (int i = 1; i <= total; ++i) parent[i] = i;
    function<int(int)> findp = [&](int x) {
        if (parent[x] != x) parent[x] = findp(parent[x]);
        return parent[x];
    };
    auto unite = [&](int a, int b) {
        if (rank[a] >= rank[b]) {
            parent[b] = a;
            ++rank[a];
        } else {
            parent[a] = b;
            ++rank[b];
        }
    };
    for (int i = 1; i <= total; ++i) {
        int val = (long long)factor * i % total;
        int pa = findp(i);
        int pb = findp(val);
        if (pa != pb) unite(pa, pb);
    }
    set<int> group_ids;
    for (int i = 1; i <= total; ++i) {
        group_ids.insert(findp(i));
    }
    long long result;
    const long long MOD = 1000000007;
    function<long long(long long, long long, long long)> fast_pow = [&](long long base, long long exp, long long mod) {
        long long res = 1;
        while (exp > 0) {
            if (exp & 1) res = (res * base) % mod;
            base = (base * base) % mod;
            exp >>= 1;
        }
        return res;
    };
    if (factor == 0) result = fast_pow(total, total - 1, MOD);
    else if (factor == 1) result = fast_pow(total, total, MOD);
    else result = fast_pow(total, (long long)group_ids.size(), MOD);
    cout << result << "\n";
    return 0;
}
